import Foundation

/// A bundled gradient used as a sleeve when a track has no artwork of its own.
///
/// Showing it â both as the rounded-rectangle cover and, blurred, as the stage
/// backdrop â means the now-playing page never branches on "no artwork": the
/// cover is always a cover and the foreground text is always light.
enum DefaultCover {
    /// Raw JPEG bytes of the default sleeve, base64-encoded.
    private static let base64 = ""

    /// Raw JPEG bytes of the default sleeve.
    static let data: Data? = Data(base64Encoded: base64)

    private static var _image: PlatformImage?
    /// The decoded default sleeve, cached after the first call.
    static var image: PlatformImage? {
        if _image == nil { _image = data.flatMap { PlatformImage.decode($0) } }
        return _image
    }

    /// True whenever the bundled asset decoded successfully.
    static var isAvailable: Bool { image != nil }
}
